 "content": "def transform(grid):
    """Fill the missing portion of a partial stripe with color 1."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    stripe_colors = [c for c in counts if c != background]
    for color in stripe_colors:
        full_rows = [r for r in range(h) if all(v == color for v in grid[r])]
        if not full_rows:
            continue
        for r in range(h):
            if any(v == color for v in grid[r]) and any(v == background for v in grid[r]):
                for c in range(w):
                    if out[r][c] == background:
                        out[r][c] = 1
    return out
